def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header: The Range header string (e.g., "bytes=0-499, 500-")
        size: The total size of the resource in bytes.

    Returns:
        A list of (start, end) inclusive byte offset tuples, or None if unsatisfiable.
    """
    if not header or not header.startswith("bytes="):
        return None

    range_spec = header[6:].strip()
    if not range_spec:
        return None

    ranges = []
    parts = range_spec.split(",")

    for part in parts:
        part = part.strip()
        if not part:
            continue

        if '-' in part:
            suffix_start = part.find('-')
            start_str = part[:suffix_start].strip()
            end_str = part[suffix_start + 1:].strip()

            if start_str == '' and end_str == '':
                # Malformed: "bytes=-"
                return None
            elif start_str == '':
                # Suffix range: bytes=-N
                try:
                    suffix_length = int(end_str)
                except ValueError:
                    return None

                if suffix_length <= 0:
                    return None

                if suffix_length >= size:
                    # Suffix length larger than resource yields the whole resource
                    ranges.append((0, size - 1))
                else:
                    start = size - suffix_length
                    end = size - 1
                    ranges.append((start, end))
            else:
                # Normal range: bytes=N-M or bytes=N-
                try:
                    start = int(start_str)
                except ValueError:
                    return None

                if start < 0:
                    return None

                if end_str == '':
                    # Open-ended range: bytes=N-
                    end = size - 1
                else:
                    try:
                        end = int(end_str)
                    except ValueError:
                        return None

                # Clamp end to size - 1
                if end > size - 1:
                    end = size - 1

                # Check if satisfiable
                if start >= size:
                    # Unsatisfiable range
                    continue
                else:
                    ranges.append((start, end))
        else:
            # Malformed: no hyphen
            return None

    if not ranges:
        return None

    return ranges
