class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = {}
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.key_to_val:
            return -1
        self._update_freq(key)
        return self.key_to_val[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity <= 0:
            return
        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._update_freq(key)
        else:
            if len(self.key_to_val) >= self.capacity:
                self._evict()
            self.key_to_val[key] = value
            self.key_to_freq[key] = 1
            if 1 not in self.freq_to_keys:
                self.freq_to_keys[1] = {}
            self.freq_to_keys[1][key] = True
            self.min_freq = 1

    def _update_freq(self, key: int) -> None:
        freq = self.key_to_freq[key]
        # Remove from current frequency bucket
        self.freq_to_keys[freq].pop(key)
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1

        # Add to new frequency bucket
        new_freq = freq + 1
        self.key_to_freq[key] = new_freq
        if new_freq not in self.freq_to_keys:
            self.freq_to_keys[new_freq] = {}
        self.freq_to_keys[new_freq][key] = True

    def _evict(self) -> None:
        # Get the least frequently used bucket
        keys = self.freq_to_keys[self.min_freq]
        # Evict the least recently used key (first inserted in the OrderedDict-like structure)
        evict_key = next(iter(keys))

        # Remove from all structures
        del self.key_to_val[evict_key]
        del self.key_to_freq[evict_key]
        del self.freq_to_keys[self.min_freq][evict_key]
        if not self.freq_to_keys[self.min_freq]:
            del self.freq_to_keys[self.min_freq]
