def lis_length(a):
    if not a:
        return 0

    import bisect
    tails = []

    for num in a:
        idx = bisect.bisect_left(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num

    return len(tails)
